// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint256[] calldata v) public {
        vm.assume(caddress != address(0));
        // If tos is empty and v is non-empty, the reference reverts
        if (_tos.length == 0 && v.length > 0) {
            (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));
            assertTrue(!success);
        } else {
            // for non-empty tos or empty v, just ensure no revert based on this condition
            vm.assume(_tos.length > 0);
            vm.assume(v.length == _tos.length);
            (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));
            assertTrue(success);
        }
    }
}

